.agent{position:absolute;z-index:7;width:30px;height:30px;border-radius:9px;border:1px solid rgba(255,255,255,.16);background:linear-gradient(135deg,rgba(114,167,255,.25),rgba(255,184,107,.16));box-shadow:0 0 18px rgba(114,167,255,.18);display:grid;place-items:center;font-family:var(--mono);font-size:13px;color:#e8f0fb;opacity:0;transform:translate(var(--ax),var(--ay)) scale(.7);transition:transform .52s cubic-bezier(.2,.8,.2,1),opacity .25s ease}.agent.on{opacity:1;transform:translate(var(--ax),var(--ay)) scale(1)}.packet{position:absolute;z-index:6;width:10px;height:10px;border-radius:50%;background:var(--green);box-shadow:0 0 16px rgba(51,209,122,.7);opacity:0;transform:translate(var(--px),var(--py));transition:transform .74s cubic-bezier(.2,.8,.2,1),opacity .18s ease}.packet.on{opacity:1}.timeline{position:absolute;left:34px;right:34px;bottom:18px;height:44px;border:1px solid var(--line);border-radius:10px;background:rgba(9,11,15,.82);display:flex;align-items:center;gap:12px;padding:0 13px;font-family:var(--mono);font-size:11px;color:var(--muted);z-index:9}.bar{height:3px;flex:1;background:#151a22;border-radius:99px;overflow:hidden}.bar span{display:block;height:100%;width:0;background:linear-gradient(90deg,var(--amber),var(--blue),var(--green));box-shadow:0 0 12px rgba(114,167,255,.4);transition:width .2s linear}.kbd{border:1px solid var(--line);border-radius:5px;padding:3px 6px;color:#cbd5e1}.final-tile{position:absolute;z-index:8;right:26px;bottom:76px;width:224px;height:126px;border:1px solid rgba(51,209,122,.48);border-radius:12px;background:linear-gradient(180deg,rgba(51,209,122,.13),rgba(114,167,255,.08),rgba(255,255,255,.024));box-shadow:0 0 38px rgba(51,209,122,.18),0 20px 50px rgba(0,0,0,.45);opacity:0;transform:translateY(24px) scale(.96);transition:.7s cubic-bezier(.2,.8,.2,1);padding:14px}.final-tile.on{opacity:1;transform:translateY(0) scale(1)}.final-tile h3{font-family:var(--mono);font-size:14px;margin:0 0 8px}.mini-bars{display:flex;gap:5px;margin-top:15px}.mini-bars span{height:27px;flex:1;border-radius:4px;background:rgba(255,255,255,.08)}.mini-bars span:nth-child(1){background:rgba(255,184,107,.32)}.mini-bars span:nth-child(2){background:rgba(114,167,255,.32)}.mini-bars span:nth-child(3){background:rgba(247,214,90,.32)}.mini-bars span:nth-child(4){background:rgba(51,209,122,.32)}
@media(max-width:900px){.stage{padding:18px}.headline{font-size:24px}.sub{display:none}.card{width:150px}.timeline{left:18px;right:18px}}
