<body>
<div class="stage">
  <header class="topbar"><div class="brand"><span class="prompt">hermes@kanban</span><span class="path">~/board</span><span class="cmd" id="cmd">render --dark --deps</span></div><div class="live"><span id="clock">00:00</span><span>dispatcher: live</span><span class="dot"></span></div></header>
  <section class="caption"><div class="headline" id="headline">Give AI a goal. <span class="amber">Watch it organize the work.</span></div><div class="sub" id="sub">Animated first cut: cards claim, move, complete, and unlock downstream dependencies.</div></section>
  <main class="board" aria-label="Animated Hermes Kanban board">
    <div class="board-header"><div class="controls"><span class="ctl"></span><span class="ctl"></span><span class="ctl"></span></div><div id="board-title">nous-kanban-demo / launch video pipeline</div><div>⌘K filter</div></div>
    <div class="lanes">
