      <section class="lane"><div class="lane-title"><span>Plan</span><span class="count" id="c1">00</span></div></section>
      <section class="lane"><div class="lane-title"><span>Parallel</span><span class="count" id="c2">00</span></div></section>
      <section class="lane"><div class="lane-title"><span>Animate/Edit</span><span class="count" id="c3">00</span></div></section>
      <section class="lane"><div class="lane-title"><span>Review</span><span class="count" id="c4">00</span></div></section>
    </div>
    <div class="links"><svg viewBox="0 0 1000 700" preserveAspectRatio="none">
      <path id="dep-brief-plan" class="dep amber" d="M115 150 C190 150 205 128 285 128"/>
      <path id="dep-plan-research" class="dep" d="M310 165 C380 165 410 96 490 96"/>
      <path id="dep-plan-design" class="dep yellow" d="M310 190 C382 190 408 258 490 258"/>
      <path id="dep-research-animate" class="dep green" d="M520 145 C596 145 620 178 694 178"/>
      <path id="dep-design-animate" class="dep green" d="M520 305 C596 305 620 235 694 235"/>
      <path id="dep-animate-edit" class="dep yellow" d="M720 260 C756 260 760 391 720 391"/>
      <path id="dep-edit-review" class="dep amber" d="M750 430 C828 430 828 230 904 230"/>
    </svg></div>
    <article class="card amber" id="brief"><div class="card-title">Make launch video</div><div class="copy">One request enters the shared board.</div><div class="meta"><span class="pill ready">ready</span><span class="id">t_goal</span></div></article>
    <article class="card blue" id="plan"><div class="card-title">Decompose workflow</div><div class="copy">Split the goal into owners, deps, and criteria.</div><div class="meta"><span class="pill waiting">waiting</span><span class="id">t_plan</span></div></article>
    <article class="card amber" id="research"><div class="card-title">Research/message</div><div class="copy">Draft the value prop and narration beats.</div><div class="meta"><span class="pill waiting">waiting</span><span class="id">t_752</span></div></article>
    <article class="card blue" id="design"><div class="card-title">Visual direction</div><div class="copy">Build dark terminal board language.</div><div class="meta"><span class="pill waiting">waiting</span><span class="id">t_fe8</span></div></article>
    <article class="card yellow" id="animate"><div class="card-title">Animate card graph</div><div class="copy">Claim work after both handoffs arrive.</div><div class="meta"><span class="pill waiting">blocked</span><span class="id">t_bc4</span></div></article>
    <article class="card amber" id="edit"><div class="card-title">Edit final cut</div><div class="copy">Polish captions, pacing, and transitions.</div><div class="meta"><span class="pill waiting">waiting</span><span class="id">t_edit</span></div></article>
    <article class="card blue" id="review"><div class="card-title">QA review</div><div class="copy">Approve or block with a clear reason.</div><div class="meta"><span class="pill waiting">waiting</span><span class="id">t_rev</span></div></article>
    <div class="agent" id="agentA">A</div><div class="agent" id="agentB">B</div><div class="packet" id="packet1"></div><div class="packet" id="packet2"></div>
    <div class="final-tile" id="final"><h3>Finished video</h3><div class="copy">Traceable from original brief through every card handoff.</div><div class="mini-bars"><span></span><span></span><span></span><span></span></div></div>
  </main>
  <div class="timeline"><span id="beat">brief</span><div class="bar"><span id="progress"></span></div><span class="kbd">space pause</span><span class="kbd">r restart</span></div>
</div>
<script>
const DURATION = 90000;
const cards = [...document.querySelectorAll('.card')];
const $ = id => document.getElementById(id);
const pos = {
  brief:[26,92], plan:[224,78], research:[424,48], design:[424,208], animate:[624,148], edit:[624,358], review:[824,198],
  stash:[-40,470]
};
const beats = [
  [0,'brief','Give AI a goal. <span class="amber">Watch it organize the work.</span>','A single prompt lands as a durable card.'],
  [7000,'claim','An agent <span class="amber">claims</span> the planning card.','Ownership becomes visible on the board.'],
  [15000,'split','The request decomposes into <span class="blue">specialist cards.</span>','Dependencies draw left to right.'],
  [27000,'parallel','Research and design run <span class="yellow">in parallel.</span>','Separate agents work in isolated spaces.'],
  [43000,'handoff','Completed parents send <span class="green">structured handoffs.</span>','Files, summaries, and decisions flow downstream.'],
  [58000,'unlock','Dependencies unlock the <span class="yellow">animation card.</span>','Fan-in turns blocked into running.'],
  [70000,'review','Review can approve or <span class="amber">block clearly.</span>','State is visible instead of buried in chat.'],
  [82000,'final','Idea → cards → <span class="green">finished work.</span>','The final tile traces back to the original brief.']
];
function setCard(id,x,y,o=1){ const el=$(id); el.style.setProperty('--x',x+'px'); el.style.setProperty('--y',y+'px'); el.style.setProperty('--o',o); }
function setPill(id,txt,cls){ const p=$(id).querySelector('.pill'); p.textContent=txt; p.className='pill '+cls; }
function count(a,b,c,d,e){ ['c0','c1','c2','c3','c4'].forEach((id,i)=>$(id).textContent=[a,b,c,d,e][i].toString().padStart(2,'0')); }
function line(id,cls){ $(id).className.baseVal='dep '+cls; }
function agent(id,x,y,on=true){ const el=$(id); el.style.setProperty('--ax',x+'px'); el.style.setProperty('--ay',y+'px'); el.classList.toggle('on',on); }
function packet(id,x,y,on=true){ const el=$(id); el.style.setProperty('--px',x+'px'); el.style.setProperty('--py',y+'px'); el.classList.toggle('on',on); }
function reset(){ cards.forEach(c=>{c.classList.remove('claimed','doneFlash','dimmed'); c.style.setProperty('--o',0);}); ['dep-brief-plan','dep-plan-research','dep-plan-design','dep-research-animate','dep-design-animate','dep-animate-edit','dep-edit-review'].forEach(id=>line(id,'')); ['agentA','agentB'].forEach(id=>$(id).classList.remove('on')); ['packet1','packet2'].forEach(id=>$(id).classList.remove('on')); $('final').classList.remove('on');
  setCard('brief',pos.brief[0],pos.brief[1],1); setCard('plan',pos.stash[0],pos.stash[1],0); setCard('research',pos.stash[0],pos.stash[1],0); setCard('design',pos.stash[0],pos.stash[1],0); setCard('animate',pos.stash[0],pos.stash[1],0); setCard('edit',pos.stash[0],pos.stash[1],0); setCard('review',pos.stash[0],pos.stash[1],0);
  setPill('brief','ready','ready'); setPill('plan','waiting','waiting'); setPill('research','waiting','waiting'); setPill('design','waiting','waiting'); setPill('animate','blocked','blocked'); setPill('edit','waiting','waiting'); setPill('review','waiting','waiting'); count(1,0,0,0,0);
}
function apply(t){ reset();
  if(t>=7000){ setCard('plan',pos.plan[0],pos.plan[1],1); line('dep-brief-plan','amber draw'); count(1,1,0,0,0); setPill('plan','running','running'); $('plan').classList.add('claimed'); agent('agentA',366,82,true); }
  if(t>=15000){ setPill('brief','done','done'); $('brief').classList.add('doneFlash'); setPill('plan','done','done'); setCard('research',pos.research[0],pos.research[1],1); setCard('design',pos.design[0],pos.design[1],1); setCard('animate',pos.animate[0],pos.animate[1],1); line('dep-brief-plan','amber lit'); line('dep-plan-research','draw'); line('dep-plan-design','yellow draw'); count(0,1,2,1,0); }
  if(t>=27000){ setPill('research','running','running'); setPill('design','running','running'); $('research').classList.add('claimed'); $('design').classList.add('claimed'); agent('agentA',565,52,true); agent('agentB',565,212,true); }
  if(t>=43000){ setPill('research','done','done'); setPill('design','done','done'); $('research').classList.add('doneFlash'); $('design').classList.add('doneFlash'); line('dep-research-animate','green draw'); line('dep-design-animate','green draw'); packet('packet1',560,132,true); packet('packet2',560,292,true); setTimeout(()=>{packet('packet1',684,190,true);packet('packet2',684,220,true)},50); }
  if(t>=58000){ setPill('animate','running','running'); $('animate').classList.add('claimed'); agent('agentA',765,150,true); line('dep-research-animate','green lit'); line('dep-design-animate','green lit'); line('dep-animate-edit','yellow draw'); setCard('edit',pos.edit[0],pos.edit[1],1); setPill('edit','ready','ready'); count(0,1,2,2,0); }
  if(t>=70000){ setPill('animate','done','done'); setPill('edit','running','running'); $('edit').classList.add('claimed'); line('dep-animate-edit','yellow lit'); setCard('review',pos.review[0],pos.review[1],1); line('dep-edit-review','amber draw'); setPill('review','blocked','blocked'); $('review').classList.add('dimmed'); count(0,1,2,2,1); }
  if(t>=76000){ setPill('review','accept','accept'); $('review').classList.remove('dimmed'); $('review').classList.add('doneFlash'); setPill('edit','done','done'); line('dep-edit-review','amber lit'); }
  if(t>=82000){ $('final').classList.add('on'); ['brief','plan','research','design','animate','edit','review'].forEach(id=>$(id).style.setProperty('--scale','.86')); count(0,0,0,0,1); }
  const beat = [...beats].reverse().find(b=>t>=b[0]) || beats[0]; $('beat').textContent=beat[1]; $('headline').innerHTML=beat[2]; $('sub').textContent=beat[3]; $('progress').style.width=(Math.min(t,DURATION)/DURATION*100)+'%'; $('clock').textContent='00:'+String(Math.floor(t/1000)).padStart(2,'0');
}
let start=performance.now(), paused=false, pauseAt=0;
function tick(now){ if(!paused){ let t=(now-start)%DURATION; apply(t); } requestAnimationFrame(tick); }
window.addEventListener('keydown',e=>{ if(e.code==='Space'){ paused=!paused; if(paused) pauseAt=performance.now()-start; else start=performance.now()-pauseAt; } if(e.key==='r'||e.key==='R'){ start=performance.now(); paused=false; }});
reset(); requestAnimationFrame(tick);
</script>
</body>
